import { BoxPlotAdapter, useBoxPlot } from '@dreadnought/react/unstyled';
const data = [{id:'a',label:'Группа A',values:[1,2,3,4,5,6,7,100,100]}];
function Summary() { const {layout,page} = useBoxPlot(); return <button onClick={() => page.change(2)}>Страница {page.page}, групп {layout.groups.length}</button>; }
export function Example() { return <BoxPlotAdapter label="Распределение" data={data} pageSize={1}><Summary /><BoxPlotAdapter.Plot tooltipContent={({defaultContent}) => <div>{defaultContent}</div>}>{({defaultContent}) => defaultContent}</BoxPlotAdapter.Plot><BoxPlotAdapter.Axis /><BoxPlotAdapter.Table /><BoxPlotAdapter.Pagination /><BoxPlotAdapter.Empty /></BoxPlotAdapter>; }
